parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error_info?.code || 500,
          message: item.json.error_info?.message || item.json.error || 'Mathpix API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'mathpix'
        }
      }
    };
  }

  try {
    const data = item.json;

    // Extract different format outputs
    const result = {
      text: data.text || '',
      latex: data.latex_styled || data.latex || '',
      latex_confidence: data.latex_confidence || 0,
      asciimath: data.asciimath || null,
      mathml: data.mathml || null,
      data: data.data || []
    };

    // Parse detected elements if available
    const elements = (data.data || []).map(d => ({
      type: d.type,
      value: d.value,
      latex: d.latex,
      position: d.position
    }));

    return {
      json: {
        success: true,
        data: {
          text: result.text,
          latex: result.latex,
          latex_display: result.latex ? `$$${result.latex}$$` : '',
          latex_inline: result.latex ? `$${result.latex}$` : '',
          confidence: result.latex_confidence,
          asciimath: result.asciimath,
          mathml: result.mathml,
          elements: elements,
          is_math: data.is_printed || data.is_handwritten || false,
          is_handwritten: data.is_handwritten || false
        },
        meta: {
          provider: 'mathpix',
          confidence: result.latex_confidence,
          detection_score: data.detection_score || 0
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse Mathpix response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'mathpix'
        }
      }
    };
  }
});

return results;
